<section class="container page-section">
	<p><a class="btn btn-outline-secondary" href="<?php echo site_url($child ? 'keluarga/anak' : 'belajar/arena'); ?>"><i class="bi bi-arrow-left me-2" aria-hidden="true"></i><?php echo $child ? 'Keluarga' : 'Arena Belajar'; ?></a></p><h1 class="h3">Progres Arena<?php echo $child ? ': '.html_escape($child['display_name']) : ' saya'; ?></h1><p>Hasil permainan dipisahkan dari nilai latihan kursus dan poin penukaran. Riwayat lama tetap tersimpan. Waktu ditampilkan dalam WIB.</p>
	<?php if ( ! $runs): ?><div class="empty-card"><h2 class="h5">Belum ada permainan Arena</h2><p>Riwayat muncul setelah satu permainan dimulai.</p></div><?php else: ?>
	<div class="row g-3"><?php foreach ($runs as $run): ?><div class="col-md-6"><article class="feature-card h-100"><p class="eyebrow"><?php echo study_arena_type($run['game_type']); ?></p><h2 class="h5"><?php echo html_escape($run['title_snapshot']); ?></h2><p><?php echo study_arena_status($run['status']); ?> · <?php echo $run['deadline_at'] ? 'Tantangan waktu' : 'Santai'; ?></p>
		<?php if ($run['game_type'] === 'memory'): ?><p><?php echo (int) $run['correct_count']; ?>/<?php echo (int) $run['question_count']; ?> pasangan · <?php echo (int) $run['moves']; ?> langkah</p><?php elseif ($run['game_type'] === 'flashcard'): ?><p><?php echo (int) $run['correct_count']; ?> kartu ditandai sudah paham pada babak ini (refleksi diri, bukan nilai ujian).</p><?php elseif ($run['game_type'] === 'english' && $run['activity_kind'] === 'lesson'): ?><p><?php echo (int) $run['position']; ?>/<?php echo (int) $run['question_count']; ?> langkah ditinjau; bukan nilai penguasaan.</p><?php elseif ($run['status'] !== 'running'): ?><p><?php echo (int) $run['correct_count']; ?>/<?php echo (int) $run['question_count']; ?> benar · <?php echo (int) round($run['correct_count'] * 100 / $run['question_count']); ?>%</p><?php endif; ?>
	<p class="small text-secondary">Aktivitas terakhir <?php echo html_escape(study_format_datetime($run['updated_at'])); ?></p><?php if ( ! $child): ?><a class="btn btn-outline-primary" href="<?php echo site_url('belajar/arena/main/'.$run['id']); ?>"><?php echo $run['status'] === 'running' ? 'Lanjutkan' : 'Lihat hasil'; ?></a><?php endif; ?></article></div><?php endforeach; ?></div>
	<nav class="d-flex flex-wrap align-items-center gap-3 mt-4" aria-label="Halaman riwayat"><?php if ($page > 1): ?><a href="<?php echo site_url($base.'?halaman='.($page - 1)); ?>">Sebelumnya</a><?php endif; ?><span>Halaman <?php echo $page; ?> dari <?php echo $page_count; ?> · <?php echo $total; ?> babak</span><?php if ($page < $page_count): ?><a href="<?php echo site_url($base.'?halaman='.($page + 1)); ?>">Berikutnya</a><?php endif; ?></nav><?php endif; ?>
</section>
